steps:
1. Create src/lib/notifications.ts — centralized notification helpers:
```typescript
'use server'; // or plain module — no 'use server' needed, it's a regular server-only import
import { supabaseAdmin } from '@/lib/supabase';

export async function notifyRecognitionReceived(userId: string, fromName: string, message: string) {
  await supabaseAdmin.from('notifications').insert({ user_id: userId, message: `${fromName} recognised you: "${message.slice(0, 80)}${message.length > 80 ? '…' : ''}"`, link: '/pulse/feedback' });
}

export async function notifyMilestone(userId: string, type: string, years?: number) {
  const label = type === 'work_anniversary' ? `Work anniversary${years ? ` — ${years} year${years === 1 ? '' : 's'}` : ''}` : type === 'birthday' ? 'Happy birthday!' : type === 'onboarding_complete' ? 'Welcome — onboarding complete!' : 'Service achievement';
  await supabaseAdmin.from('notifications').insert({ user_id: userId, message: `Milestone: ${label}`, link: '/pulse' });
}

export async function notifyCampaignLive(userId: string, campaignName: string) {
  await supabaseAdmin.from('notifications').insert({ user_id: userId, message: `Campaign now live: ${campaignName}`, link: '/pulse/campaigns' });
}

export async function notifyQuestEndingSoon(userId: string, questTitle: string, endsAt: string) {
  const dt = new Date(endsAt).toLocaleDateString('en-KE', { day: 'numeric', month: 'short' });
  await supabaseAdmin.from('notifications').insert({ user_id: userId, message: `Side Quest ending soon (${dt}): ${questTitle}`, link: '/pulse/side-quests' });
}

export async function notifySurveyClosingSoon(userId: string, surveyTitle: string, closesAt: string) {
  const dt = new Date(closesAt).toLocaleDateString('en-KE', { day: 'numeric', month: 'short' });
  await supabaseAdmin.from('notifications').insert({ user_id: userId, message: `Survey closing soon (${dt}): ${surveyTitle}`, link: '/pulse/surveys' });
}

export async function notifyWeeklyDigest(userId: string, summary: { questsCompleted: number; recognitionReceived: number }) {
  const parts: string[] = [];
  if (summary.recognitionReceived > 0) parts.push(`${summary.recognitionReceived} recognition${summary.recognitionReceived === 1 ? '' : 's'} received`);
  if (summary.questsCompleted > 0) parts.push(`${summary.questsCompleted} Side Quest${summary.questsCompleted === 1 ? '' : 's'} completed`);
  if (!parts.length) return;
  await supabaseAdmin.from('notifications').insert({ user_id: userId, message: `Your week: ${parts.join(', ')}.`, link: '/pulse' });
}
```

3. Update vercel.json at repo root to add cron configuration:
```json
{
  "crons": [
    { "path": "/api/pulse/notifications/reminders", "schedule": "0 8 * * 1" },
    { "path": "/api/pulse/milestones/generate", "schedule": "0 7 * * *" },
    { "path": "/api/pulse/automations/run", "schedule": "0 9 * * *" }
  ]
}
```
  Note: milestones/generate and automations/run routes are created in FEAT-003. Adding them to vercel.json here ensures the file is not overwritten later.
